class NumberTheory:
    class Mod998:
        def __init__(self):
            self.mod = 998244353
            self.inv_cache = {}

        def modulus(self):
            return self.mod

        def add(self, a, b):
            return (a + b) % self.mod

        def subtract(self, a, b):
            return (a - b) % self.mod

        def mult(self, a, b, inv_b=None):
            if inv_b is not None:
                return (a * inv_b) % self.mod
            else:
                return (a * b) % self.mod

        def smallInv(self, x):
            # Fermat's little theorem for modular inverse
            if x in self.inv_cache:
                return self.inv_cache[x]
            inv = pow(x, self.mod - 2, self.mod)
            self.inv_cache[x] = inv
            return inv

        def fInv(self, x):
            # Not used directly in Python translation, but included for completeness
            return self.smallInv(x)

        def ncr(self, n, r):
            if r < 0 or r > n:
                return 0
            numerator = 1
            denominator = 1
            for i in range(r):
                numerator = (numerator * (n - i)) % self.mod
                denominator = (denominator * (i + 1)) % self.mod
            return (numerator * self.smallInv(denominator)) % self.mod

def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    n = int(data[0])
    m = int(data[1])

    mod = NumberTheory.Mod998()
    mod.fInv(n + m)

    phaseSize = 1
    p = 1
    i = 0
    while p != 0:
        p = (p * (n - i)) % mod.mod
        inv_val = mod.smallInv(n + m - i)
        p = (p * inv_val) % mod.mod
        phaseSize = (phaseSize + p) % mod.mod
        i += 1

    answer = 0
    for k in range(1, n + 1):
        comb = mod.ncr(n, k)
        term = (comb * (m + k)) % mod.mod
        inv_k = mod.smallInv(k)
        term = (term * inv_k) % mod.mod
        term = (term * phaseSize) % mod.mod
        if k % 2 == 1:
            answer = (answer + term) % mod.mod
        else:
            answer = (answer - term) % mod.mod

    print(answer)

if __name__ == "__main__":
    main()
